import React from 'react';
import { Link } from 'react-router-dom';
import { 
  ChatBubbleLeftRightIcon,
  DevicePhoneMobileIcon,
  BoltIcon,
  ShieldCheckIcon,
  ChartBarIcon,
  CogIcon,
  CheckIcon,
  ArrowRightIcon,
  PlayIcon
} from '@heroicons/react/24/outline';

const LandingPage = () => {
  const features = [
    {
      icon: ChatBubbleLeftRightIcon,
      title: 'Multi-Device WhatsApp',
      description: 'Kelola unlimited device WhatsApp dalam satu platform dengan session persistence dan auto-reconnect.'
    },
    {
      icon: BoltIcon,
      title: 'Auto-Reply Engine',
      description: 'Sistem balasan otomatis cerdas dengan rule-based triggers dan conditional logic.'
    },
    {
      icon: DevicePhoneMobileIcon,
      title: 'Campaign & Blast',
      description: 'Kirim pesan massal dengan targeting audience dan scheduling yang fleksibel.'
    },
    {
      icon: ShieldCheckIcon,
      title: 'AI Integration',
      description: '9 fitur AI untuk optimasi konten, sentiment analysis, dan personalisasi pesan.'
    },
    {
      icon: ChartBarIcon,
      title: 'Analytics & Reports',
      description: 'Dashboard analytics lengkap dengan real-time monitoring dan performance tracking.'
    },
    {
      icon: CogIcon,
      title: 'Webhook System',
      description: 'Event-driven notifications dengan custom endpoints dan retry logic.'
    }
  ];

  const plans = [
    {
      name: 'Starter',
      price: 'Rp 299.000',
      period: '/bulan',
      description: 'Perfect untuk bisnis kecil',
      features: [
        '3 WhatsApp Device',
        '1.000 Pesan/bulan',
        'Auto-Reply Basic',
        'Campaign Tools',
        'Analytics Dashboard',
        'Email Support'
      ],
      popular: false
    },
    {
      name: 'Professional',
      price: 'Rp 599.000',
      period: '/bulan',
      description: 'Untuk bisnis yang berkembang',
      features: [
        '10 WhatsApp Device',
        '10.000 Pesan/bulan',
        'Auto-Reply Advanced',
        'AI Integration',
        'Webhook System',
        'Priority Support',
        'Custom Branding'
      ],
      popular: true
    },
    {
      name: 'Enterprise',
      price: 'Custom',
      period: '',
      description: 'Solusi untuk perusahaan besar',
      features: [
        'Unlimited Device',
        'Unlimited Pesan',
        'Full AI Features',
        'Custom Integration',
        'Dedicated Support',
        'SLA Guarantee',
        'On-premise Option'
      ],
      popular: false
    }
  ];

  return (
    <div className="min-h-screen">
      {/* Navigation */}
      <nav className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center">
              <div className="flex-shrink-0 flex items-center">
                <ChatBubbleLeftRightIcon className="h-8 w-8 text-whatsapp-600" />
                <span className="ml-2 text-xl font-bold text-gray-900">
                  WhatsApp Gateway
                </span>
              </div>
            </div>
            <div className="flex items-center space-x-4">
              <Link
                to="/login"
                className="text-gray-600 hover:text-gray-900 px-3 py-2 text-sm font-medium"
              >
                Login
              </Link>
              <Link
                to="/register"
                className="btn-primary"
              >
                Daftar Gratis
              </Link>
            </div>
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <section className="relative bg-gradient-to-br from-whatsapp-50 to-primary-50 overflow-hidden">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-24">
          <div className="text-center">
            <h1 className="text-4xl md:text-6xl font-bold text-gray-900 mb-6">
              <span className="text-gradient">WhatsApp Gateway</span>
              <br />
              untuk Bisnis Modern
            </h1>
            <p className="text-xl text-gray-600 mb-8 max-w-3xl mx-auto">
              Platform WhatsApp Business API terlengkap dengan fitur multi-device, 
              auto-reply, campaign blast, AI integration, dan analytics real-time.
            </p>
            <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <Link
                to="/register"
                className="btn-primary text-lg px-8 py-3"
              >
                Mulai Gratis
                <ArrowRightIcon className="ml-2 h-5 w-5" />
              </Link>
              <button className="btn-outline text-lg px-8 py-3">
                <PlayIcon className="mr-2 h-5 w-5" />
                Lihat Demo
              </button>
            </div>
          </div>
        </div>
        
        {/* Background decoration */}
        <div className="absolute top-0 right-0 -mt-20 -mr-20 w-80 h-80 bg-whatsapp-200 rounded-full opacity-20 animate-float"></div>
        <div className="absolute bottom-0 left-0 -mb-20 -ml-20 w-60 h-60 bg-primary-200 rounded-full opacity-20 animate-float" style={{ animationDelay: '1s' }}></div>
      </section>

      {/* Features Section */}
      <section className="py-24 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Fitur Lengkap untuk Bisnis Anda
            </h2>
            <p className="text-xl text-gray-600 max-w-2xl mx-auto">
              Semua yang Anda butuhkan untuk mengotomatisasi dan mengoptimalkan komunikasi WhatsApp bisnis.
            </p>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {features.map((feature, index) => (
              <div key={index} className="card hover:shadow-lg transition-shadow duration-300">
                <div className="flex items-center mb-4">
                  <div className="flex-shrink-0">
                    <feature.icon className="h-8 w-8 text-whatsapp-600" />
                  </div>
                  <h3 className="ml-3 text-xl font-semibold text-gray-900">
                    {feature.title}
                  </h3>
                </div>
                <p className="text-gray-600">
                  {feature.description}
                </p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Stats Section */}
      <section className="py-16 bg-gray-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-8 text-center">
            <div>
              <div className="text-3xl md:text-4xl font-bold text-whatsapp-600 mb-2">1000+</div>
              <div className="text-gray-600">Bisnis Terdaftar</div>
            </div>
            <div>
              <div className="text-3xl md:text-4xl font-bold text-whatsapp-600 mb-2">50M+</div>
              <div className="text-gray-600">Pesan Terkirim</div>
            </div>
            <div>
              <div className="text-3xl md:text-4xl font-bold text-whatsapp-600 mb-2">99.9%</div>
              <div className="text-gray-600">Uptime</div>
            </div>
            <div>
              <div className="text-3xl md:text-4xl font-bold text-whatsapp-600 mb-2">24/7</div>
              <div className="text-gray-600">Support</div>
            </div>
          </div>
        </div>
      </section>

      {/* Pricing Section */}
      <section className="py-24 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Pilih Paket yang Tepat
            </h2>
            <p className="text-xl text-gray-600">
              Mulai gratis, upgrade kapan saja sesuai kebutuhan bisnis Anda.
            </p>
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {plans.map((plan, index) => (
              <div key={index} className={`card relative ${plan.popular ? 'ring-2 ring-whatsapp-500 shadow-lg' : ''}`}>
                {plan.popular && (
                  <div className="absolute -top-4 left-1/2 transform -translate-x-1/2">
                    <span className="bg-whatsapp-500 text-white px-4 py-1 rounded-full text-sm font-medium">
                      Paling Populer
                    </span>
                  </div>
                )}
                
                <div className="text-center mb-6">
                  <h3 className="text-2xl font-bold text-gray-900 mb-2">{plan.name}</h3>
                  <p className="text-gray-600 mb-4">{plan.description}</p>
                  <div className="flex items-baseline justify-center">
                    <span className="text-4xl font-bold text-gray-900">{plan.price}</span>
                    <span className="text-gray-600 ml-1">{plan.period}</span>
                  </div>
                </div>
                
                <ul className="space-y-3 mb-8">
                  {plan.features.map((feature, featureIndex) => (
                    <li key={featureIndex} className="flex items-center">
                      <CheckIcon className="h-5 w-5 text-whatsapp-500 mr-3 flex-shrink-0" />
                      <span className="text-gray-600">{feature}</span>
                    </li>
                  ))}
                </ul>
                
                <Link
                  to="/register"
                  className={`w-full ${plan.popular ? 'btn-success' : 'btn-outline'}`}
                >
                  {plan.name === 'Enterprise' ? 'Hubungi Sales' : 'Mulai Sekarang'}
                </Link>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section className="py-16 bg-gradient-whatsapp">
        <div className="max-w-4xl mx-auto text-center px-4 sm:px-6 lg:px-8">
          <h2 className="text-3xl md:text-4xl font-bold text-white mb-4">
            Siap Mengotomatisasi WhatsApp Bisnis Anda?
          </h2>
          <p className="text-xl text-whatsapp-100 mb-8">
            Bergabung dengan ribuan bisnis yang sudah mempercayai platform kami.
          </p>
          <Link
            to="/register"
            className="btn bg-white text-whatsapp-600 hover:bg-gray-50 text-lg px-8 py-3"
          >
            Daftar Gratis Sekarang
          </Link>
        </div>
      </section>

      {/* Footer */}
      <footer className="bg-gray-900 text-white py-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
            <div>
              <div className="flex items-center mb-4">
                <ChatBubbleLeftRightIcon className="h-8 w-8 text-whatsapp-500" />
                <span className="ml-2 text-xl font-bold">WhatsApp Gateway</span>
              </div>
              <p className="text-gray-400">
                Platform WhatsApp Business API terlengkap untuk bisnis modern.
              </p>
            </div>
            
            <div>
              <h3 className="text-lg font-semibold mb-4">Produk</h3>
              <ul className="space-y-2 text-gray-400">
                <li><a href="#" className="hover:text-white">WhatsApp API</a></li>
                <li><a href="#" className="hover:text-white">Auto Reply</a></li>
                <li><a href="#" className="hover:text-white">Campaign Tools</a></li>
                <li><a href="#" className="hover:text-white">AI Integration</a></li>
              </ul>
            </div>
            
            <div>
              <h3 className="text-lg font-semibold mb-4">Dukungan</h3>
              <ul className="space-y-2 text-gray-400">
                <li><a href="#" className="hover:text-white">Dokumentasi</a></li>
                <li><a href="#" className="hover:text-white">API Reference</a></li>
                <li><a href="#" className="hover:text-white">Support Center</a></li>
                <li><a href="#" className="hover:text-white">Status Page</a></li>
              </ul>
            </div>
            
            <div>
              <h3 className="text-lg font-semibold mb-4">Perusahaan</h3>
              <ul className="space-y-2 text-gray-400">
                <li><a href="#" className="hover:text-white">Tentang Kami</a></li>
                <li><a href="#" className="hover:text-white">Blog</a></li>
                <li><a href="#" className="hover:text-white">Karir</a></li>
                <li><a href="#" className="hover:text-white">Kontak</a></li>
              </ul>
            </div>
          </div>
          
          <div className="border-t border-gray-800 mt-8 pt-8 text-center text-gray-400">
            <p>&copy; 2026 WhatsApp Gateway SaaS. All rights reserved.</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default LandingPage;